#pragma once
namespace portalis {
static const char kTransferPage[]=R"HTML(<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portalis SD Explorer</title>
<style>
:root{color-scheme:dark;font:15px system-ui;background:#0b1220;color:#e5eef7}*{box-sizing:border-box}body{margin:0}header{padding:22px 28px;border-bottom:1px solid #2b3c52;display:flex;justify-content:space-between;align-items:center}h1{font-size:23px;margin:0;color:#73e4cf}header small{color:#a8bbce}.layout{display:grid;grid-template-columns:180px minmax(0,1fr);min-height:80vh}aside{padding:22px 14px;background:#101b2c;border-right:1px solid #2b3c52}aside button{display:block;width:100%;text-align:left;margin-bottom:8px}main{padding:24px;min-width:0}button,.download{font:inherit;color:#e5eef7;background:#1c2b41;border:1px solid #3a4c64;border-radius:7px;padding:9px 12px;cursor:pointer;text-decoration:none;white-space:nowrap}button:hover,.download:hover{background:#2e4561}button:disabled{opacity:.4;cursor:default}.primary{background:#73e4cf;color:#07352d;border-color:#73e4cf}nav,.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px;align-items:center}nav button{border:0;background:none;color:#73e4cf;padding:4px;white-space:normal;overflow-wrap:anywhere}.toolbar .spacer{flex:1}.muted{color:#a8bbce}#message{min-height:24px;white-space:pre-wrap;overflow-wrap:anywhere}#drop{border:1px solid #2b3c52;border-radius:10px;overflow:hidden}#drop.drag{outline:2px dashed #73e4cf}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{text-align:left;padding:13px 14px;border-bottom:1px solid #26374d}th{background:#132036;font-size:12px;text-transform:uppercase;color:#a8bbce}th:nth-child(2){width:100px}th:last-child{width:260px}td:first-child{overflow-wrap:anywhere}.name{background:none;border:0;padding:0;color:#73e4cf;white-space:normal;text-align:left}.actions{display:flex;gap:6px;flex-wrap:wrap}.actions button,.actions a{font-size:12px;padding:7px}.danger{color:#ffadad}#empty{text-align:center;padding:36px;color:#a8bbce}.bottom{display:flex;align-items:center;justify-content:space-between;margin-top:16px;gap:12px}progress{width:100%;height:7px;accent-color:#73e4cf}input[type=file]{display:none}:focus-visible{outline:2px solid #73e4cf;outline-offset:3px}@media(max-width:700px){header{padding:18px}header small{display:none}.layout{display:block}aside{display:flex;gap:6px;overflow:auto;padding:12px;border-right:0}aside button{width:auto;margin:0}main{padding:14px}th:nth-child(2),td:nth-child(2){display:none}th:last-child{width:132px}th,td{padding:10px}.actions{gap:4px}.bottom{flex-wrap:wrap}}
</style></head><body><header><h1>Portalis <span style="color:#e5eef7">SD Explorer</span></h1><small>Connected to your Cardputer</small></header>
<div class="layout"><aside aria-label="Quick access"><button data-path="/">SD card</button><button data-path="/scripts">Scripts</button><button data-path="/captures">Captures</button><button data-path="/surveys">Surveys</button></aside><main>
<nav id="breadcrumbs" aria-label="Folder path"></nav><div class="toolbar"><button id="up">↑ Up</button><button id="refresh">Refresh</button><span class="spacer"></span><button id="newfolder">New folder</button><button id="newfile">New file</button><button id="upload" class="primary">↑ Upload files</button><input type="file" id="files" multiple></div>
<p class="muted">Browse the entire SD card. Drop files here to upload (up to 32 MiB per file).</p><p id="message" role="status" aria-live="polite"></p><progress id="progress" max="100" value="0" hidden></progress>
<div id="drop"><table><thead><tr><th>Name</th><th>Size</th><th>Actions</th></tr></thead><tbody id="entries"></tbody></table><div id="empty" hidden>This folder is empty.</div></div><div class="bottom"><span id="count" class="muted"></span><div><button id="prev">Previous</button> <button id="next">Next</button></div></div>
</main></div><script>
const token='@@TOKEN@@', $=s=>document.querySelector(s);let folder='/',offset=0,more=false,busy=false;
const join=(p,n)=>p+(p==='/'?'':'/')+n,parent=p=>p.slice(0,p.lastIndexOf('/'))||'/';
function lock(value){busy=value;document.querySelectorAll('button').forEach(b=>b.disabled=value);document.querySelectorAll('.download').forEach(a=>{a.style.pointerEvents=value?'none':'';a.tabIndex=value?-1:0;});if(!value){$('#up').disabled=folder==='/';$('#prev').disabled=!offset;$('#next').disabled=!more;}}
function button(label,action,cls=''){const b=document.createElement('button');b.textContent=label;b.className=cls;b.onclick=action;return b;}
function size(n){return n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KiB':(n/1048576).toFixed(1)+' MiB';}
function crumbs(){const nav=$('#breadcrumbs');nav.replaceChildren(button('SD card',()=>navigate('/')));let p='';for(const part of folder.split('/').filter(Boolean)){p+='/'+part;const target=p;nav.append(document.createTextNode('/'),button(part,()=>navigate(target)));}}
async function list(path=folder,page=offset){const r=await fetch('/list?path='+encodeURIComponent(path)+'&offset='+page,{cache:'no-store'});if(!r.ok)throw Error(await r.text());const data=await r.json();folder=path;offset=page;more=data.more;crumbs();const body=$('#entries');body.replaceChildren();data.files.sort((a,b)=>Number(b.directory)-Number(a.directory)||a.name.localeCompare(b.name));for(const item of data.files){const path=join(folder,item.name),tr=document.createElement('tr'),name=document.createElement('td'),bytes=document.createElement('td'),actions=document.createElement('td');const label=(item.directory?'📁 ':'📄 ')+item.name;if(item.directory)name.append(button(label,()=>navigate(path),'name'));else name.textContent=label;bytes.textContent=item.directory?'—':size(item.size);const group=document.createElement('div');group.className='actions';if(!item.directory){const a=document.createElement('a');a.textContent='Download';a.className='download';a.href='/download?path='+encodeURIComponent(path);a.download=item.name;group.append(a);}group.append(button('Rename',()=>rename(path,item.name)),button('Delete',()=>remove(path,item.directory),'danger'));actions.append(group);tr.append(name,bytes,actions);body.append(tr);}$('#empty').hidden=!!data.files.length;$('#count').textContent=data.files.length?'Items '+(offset+1)+'–'+(offset+data.files.length)+(more?' · more available':''):'0 items';}
async function run(action){if(busy)return;lock(true);$('#message').textContent='';try{await action();}catch(e){$('#message').textContent=e.message;}finally{lock(false);}}
function navigate(path,page=0){return run(()=>list(path,page));}
async function mutation(action,args){const r=await fetch('/'+action,{method:'POST',headers:{'X-Portalis-Token':token,'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(args)});if(!r.ok)throw Error(await r.text());}
function create(directory){const name=prompt(directory?'New folder name':'New empty file name');if(!name)return;run(async()=>{await mutation(directory?'mkdir':'create',{path:join(folder,name)});await list(folder,0);$('#message').textContent='Created '+name;});}
function rename(path,old){const name=prompt('New name',old);if(!name||name===old)return;run(async()=>{await mutation('rename',{path,name});await list();$('#message').textContent='Renamed to '+name;});}
function remove(path,directory){if(!confirm('Permanently delete '+path+(directory?' and everything inside it':'')+'? This cannot be undone.'))return;run(async()=>{try{await mutation('delete',{path,confirm:'yes'});}catch(e){await list(folder,0);throw e;}await list(folder,0);$('#message').textContent='Deleted '+path;});}
function uploadOne(file,replace){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/upload?path='+encodeURIComponent(folder)+'&replace='+(replace?'1':'0'));xhr.setRequestHeader('X-Portalis-Token',token);xhr.upload.onprogress=e=>{if(e.lengthComputable)$('#progress').value=e.loaded/e.total*100;};xhr.onload=()=>resolve({status:xhr.status,text:xhr.responseText});xhr.onerror=()=>reject(Error('Upload connection lost. Check the Cardputer and refresh.'));const data=new FormData();data.append('file',file);xhr.send(data);});}
function upload(files){const selected=Array.from(files);if(!selected.length)return;run(async()=>{let saved=0,skipped=0;$('#progress').hidden=false;try{for(const file of selected){if(file.size>33554432)throw Error(file.name+' exceeds 32 MiB');$('#message').textContent='Uploading '+file.name+'…';let r=await uploadOne(file,false);if(r.status===409){if(!confirm('Replace existing file '+file.name+'?')){skipped++;continue;}r=await uploadOne(file,true);}if(r.status!==200)throw Error(file.name+': '+r.text);saved++;}await list(folder,0);$('#message').textContent=saved+' uploaded'+(skipped?', '+skipped+' skipped':'');}finally{$('#progress').hidden=true;$('#files').value='';}});}
document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>navigate(b.dataset.path));$('#up').onclick=()=>navigate(parent(folder));$('#refresh').onclick=()=>navigate(folder,offset);$('#prev').onclick=()=>navigate(folder,Math.max(0,offset-64));$('#next').onclick=()=>navigate(folder,offset+64);$('#newfolder').onclick=()=>create(true);$('#newfile').onclick=()=>create(false);$('#upload').onclick=()=>$('#files').click();$('#files').onchange=e=>upload(e.target.files);
const drop=$('#drop');drop.ondragover=e=>{e.preventDefault();if(!busy)drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');if(!busy)upload(e.dataTransfer.files);};window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>e.preventDefault());navigate('/');
</script></body></html>)HTML";
}
